// === Tab: mySketch ===
let balls = [];

function setup() {
	createCanvas(400, 400);
	for (let i = 0; i < 10; i++) {
		balls.push(new Ball(random(width), random(height)));
	}
}

function draw() {
	//background(220,30);
	translate(200, 200);
	//stroke(0);
	noStroke();

	for (let b of balls) {
		b.update();
		b.display();
	}
}

class Ball {
	constructor(x, y) {
		this.x = x;
		this.y = y;
		this.size = random(5, 50);
		this.angle = 0;
		this.c = color(random(255), random(255), random(255), 50);
	}
	update() {
		let a = sin(frameCount * 0.001) * 200;
		let b = noise(frameCount * 0.1) * 100;
		this.x = a;
		this.y = b;
		this.angle += 0.01;
	}
	display() {
		rotate(this.angle);
		fill(this.c);
		circle(this.x, this.y, this.size);
	}
}

